  UNION ALL SELECT 'Digital transformation' AS t, 0 AS c, 'Look at what changed: only the format of the paper. The process itself did not change.' AS e, 1 AS s
  UNION ALL SELECT 'Digitalisation' AS t, 0 AS c, 'Look at what changed: only the format of the paper. The process itself did not change.' AS e, 2 AS s
  UNION ALL SELECT 'Cloud migration' AS t, 0 AS c, 'Look at what changed: only the format of the paper. The process itself did not change.' AS e, 3 AS s) o WHERE @q > 0;
