  UNION ALL SELECT 'Rethinking how a service works, using what digital technology makes possible' AS t, 1 AS c, 'Transformation changes the service itself, not only the tools used to deliver the old one.' AS e, 1 AS s
  UNION ALL SELECT 'Moving all documents to a shared drive' AS t, 0 AS c, 'Those can be part of it, but on their own they just do the old thing with newer tools.' AS e, 2 AS s
