  UNION ALL SELECT 'The tenant\'s phone' AS t, 0 AS c, 'Think about where decisions and rules are applied, not where things are displayed or carried.' AS e, 1 AS s
  UNION ALL SELECT 'The back end, where business rules are applied' AS t, 1 AS c, 'Business rules such as priority logic live in the back end.' AS e, 2 AS s
  UNION ALL SELECT 'The internet cables' AS t, 0 AS c, 'Think about where decisions and rules are applied, not where things are displayed or carried.' AS e, 3 AS s) o WHERE @q > 0;
