INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'It stores all the records permanently' AS t, 0 AS c, 'Storing is the database\'s job and screens are the front end\'s. The API passes messages between them.' AS e, 0 AS s
  UNION ALL SELECT 'It draws the screens people see' AS t, 0 AS c, 'Storing is the database\'s job and screens are the front end\'s. The API passes messages between them.' AS e, 1 AS s
  UNION ALL SELECT 'It makes the website load faster' AS t, 0 AS c, 'Storing is the database\'s job and screens are the front end\'s. The API passes messages between them.' AS e, 2 AS s
