INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'A tenant tells you: "I reported a damp problem on your website last week and I\'ve heard nothing. When I phoned, customer support had no record of it." Using the layers from this module (person, front end, API, back end, database), list the places this could have gone wrong, and which one you would ask the supplier to check first. Why?', 'Several layers could be at fault, which is exactly why "which layer?" is such a good first question. The front end might have shown a success message without actually sending anything. The API call might have failed silently, so the message never reached the back end. The back end might have received it but rejected it because a rule failed (a missing field, say) without telling anyone. The record might have been saved to the database but customer support\'s system might not be reading from the same place, which is an integration problem. A sensible first check is whether the repair exists in the database at all: if it does, the problem is downstream (integration or display); if it does not, the problem is upstream (front end, API or back end). Asking for logs of the request is the way a supplier would trace it.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Module 2: A Short History of It All =====
INSERT INTO pm_learning_modules (course_id, title, description, sort_order)
SELECT @course, 'A Short History of It All', 'Six moments, from 1843 to 1993, that explain why computers, the internet and the web look the way they do today. Follow the timeline on the course page.', 2 FROM DUAL WHERE @course > 0;
SET @mod := IF(@course > 0, LAST_INSERT_ID(), 0);

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Ada Lovelace and the idea of a programmable machine', 'Where the idea of software began, a century before the first modern computers.', '![Ada Lovelace, 1840, portrait by Alfred Edward Chalon](https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Ada_Lovelace_Chalon_portrait.jpg/330px-Ada_Lovelace_Chalon_portrait.jpg)\n\n## A machine that could follow instructions\n\nIn the 1830s the mathematician Charles Babbage designed the **Analytical Engine**, a mechanical calculator that could in principle be given different sets of instructions to carry out different tasks. It was never fully built, but the design contained the key ideas of every computer since: a processing unit, a memory, and instructions fed in from outside.\n\nIn 1843 Ada Lovelace published a set of notes on the machine that ran to roughly three times the length of the article they were attached to. Among them was a step-by-step method for the engine to calculate a sequence of numbers (Bernoulli numbers), which is often described as the first published computer program.\n\n## The insight that matters for you\n\nLovelace\'s real leap was seeing that such a machine need not be limited to arithmetic. If you could represent other things, such as music or letters, as numbers, the machine could manipulate those too. That is the idea behind everything digital: **if you can turn something into numbers, a machine can store it, copy it and work on it.**\n\nA repair request, a photo of a damp wall, a postcode, an invoice: all of them become numbers once they are digital. That is why one piece of software can handle all of them.\n\n## Software versus hardware\n\nLovelace also separated the machine (**hardware**) from the instructions it follows (**software**). That split still defines the industry. The same phone becomes a camera, a map, a bank or a repair-reporting tool just by changing the software. And it is why a "system" is never a single thing: it is hardware, software and data working together.\n\n::: try\nLook at the phone in your pocket. Count how many different jobs it does today that once needed a separate physical device (camera, torch, calculator, map, diary, bank branch, radio). One machine, many jobs, because the jobs are software.\n:::\n\n## Further reading\n\n- [Ada Lovelace (Wikipedia)](https://en.wikipedia.org/wiki/Ada_Lovelace)', 1, '1843', 1843 FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'What was the key insight attributed to Ada Lovelace?', 0 FROM DUAL WHERE @lesson > 0;
SET @q := IF(@lesson > 0, LAST_INSERT_ID(), 0);
