  UNION ALL SELECT 'Computers should be powered by electricity' AS t, 0 AS c, 'Those came much later or are not what she wrote about.' AS e, 1 AS s
  UNION ALL SELECT 'Computers need a connection to the internet' AS t, 0 AS c, 'Those came much later or are not what she wrote about.' AS e, 2 AS s
  UNION ALL SELECT 'Every business should have its own computer' AS t, 0 AS c, 'Those came much later or are not what she wrote about.' AS e, 3 AS s) o WHERE @q > 0;
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'Why is the hardware / software split useful to understand?', 1 FROM DUAL WHERE @lesson > 0;
SET @q := IF(@lesson > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'Hardware never needs replacing' AS t, 0 AS c, 'It is almost the opposite: software is what makes one machine flexible.' AS e, 0 AS s
  UNION ALL SELECT 'The same machine can do completely different jobs just by changing its software' AS t, 1 AS c, 'That is why a phone can be a camera, a map and a bank.' AS e, 1 AS s
  UNION ALL SELECT 'Software only works on one type of machine' AS t, 0 AS c, 'It is almost the opposite: software is what makes one machine flexible.' AS e, 2 AS s
  UNION ALL SELECT 'It explains how the internet is routed' AS t, 0 AS c, 'It is almost the opposite: software is what makes one machine flexible.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Alan Turing and the universal machine', 'The idea that one machine can run any program, and why a phone is a "general purpose" computer.', '![Alan Turing aged 16](https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Alan_Turing_Aged_16.jpg/330px-Alan_Turing_Aged_16.jpg)\n\n## One machine to do any job\n\nIn 1936 the British mathematician Alan Turing published a paper describing an imaginary machine that reads and writes symbols on a tape according to a table of rules. The significance was a proof that a single, simple machine of this type could, given the right rules, carry out **any calculation that any other machine could**. This is the **universal machine**, and it is the theoretical ancestor of every laptop, phone and server.\n\nBefore this, you might imagine a separate machine for each task. After it, the path was clear to one general-purpose machine that takes its instructions as data. Software is that data.\n\n## Codebreaking and the first real computers\n\nDuring the Second World War, Turing worked at Bletchley Park, helping to break German Enigma messages. The war accelerated the building of the first electronic computers (including Colossus, built in Britain to break another German cipher). By the late 1940s and 1950s, computers were being built that stored programs in memory, the design that remains standard today.\n\n## From room-sized to pocket-sized\n\nEarly computers filled rooms and cost fortunes, and were used by governments, universities and large firms. Two developments made them everyday objects: the **transistor** and later the **integrated circuit** (the "chip"), which let thousands, then billions, of tiny switches be etched on a sliver of silicon. This is why the phone in your pocket is millions of times more powerful than the computers that sent people to the Moon.\n\n::: repairs\nMany council systems still contain ideas from this era. Some of the oldest housing and finance systems were first designed in the 1980s or earlier. That is not automatically bad, but it explains why connecting them to modern tools can be hard. We return to this in the module on applications.\n:::\n\n## Further reading\n\n- [Alan Turing (Bletchley Park)](https://bletchleypark.org.uk/roll-of-honour/4426)', 2, '1936', 1936 FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'What did Turing\'s 1936 idea of the universal machine show?', 0 FROM DUAL WHERE @lesson > 0;
SET @q := IF(@lesson > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'That computers needed to be connected to each other' AS t, 0 AS c, 'It showed roughly the opposite: one general machine can do the work of many specialised ones.' AS e, 0 AS s
  UNION ALL SELECT 'That every task needs its own special machine' AS t, 0 AS c, 'It showed roughly the opposite: one general machine can do the work of many specialised ones.' AS e, 1 AS s
  UNION ALL SELECT 'A single machine could carry out any calculation, given the right instructions' AS t, 1 AS c, 'This is why one phone can run millions of different apps.' AS e, 2 AS s
  UNION ALL SELECT 'That data should be stored in tables' AS t, 0 AS c, 'It showed roughly the opposite: one general machine can do the work of many specialised ones.' AS e, 3 AS s) o WHERE @q > 0;
