SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'The telephone and the television' AS t, 0 AS c, 'Those are important, but they came later and sit on top of the hardware.' AS e, 0 AS s
  UNION ALL SELECT 'The modem and the web browser' AS t, 0 AS c, 'Those are important, but they came later and sit on top of the hardware.' AS e, 1 AS s
  UNION ALL SELECT 'The database and the spreadsheet' AS t, 0 AS c, 'Those are important, but they came later and sit on top of the hardware.' AS e, 2 AS s
  UNION ALL SELECT 'The transistor and the integrated circuit (chip)' AS t, 1 AS c, 'Etching billions of tiny switches onto silicon shrank computers from rooms to pockets.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'ARPANET: the first message', 'How a US research project sent the first message between two computers, and why the internet was designed to survive failures.', '![wide: ARPANET logical map, September 1973. Each dot is a university or research site. Click to open full size.](https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/ARPA_Network%2C_Logical_Map%2C_September_1973.jpg/960px-ARPA_Network%2C_Logical_Map%2C_September_1973.jpg)\n\n## Two computers, one word\n\nOn 29 October 1969, researchers at the University of California, Los Angeles tried to send the word "LOGIN" to a computer at the Stanford Research Institute, over 500 km away. The system crashed after the first two letters, so the first message ever sent over what became the internet was, accidentally, "LO". It was fixed within the hour and the full word went through.\n\nThe network was **ARPANET**, funded by the US Department of Defense\'s research agency. The map on this page shows it four years later, in 1973, with each dot a university or research site.\n\n## The design idea that still matters: packet switching\n\nEarlier networks, like the telephone system, worked by reserving a dedicated line between two people for the length of a call. ARPANET used a different approach, developed by researchers including Paul Baran in the US and Donald Davies at the UK\'s National Physical Laboratory: break each message into small chunks called **packets**, label each with its destination, and send them separately over whatever route is free. At the other end they are put back together.\n\nThis had a huge consequence: **there is no single point of failure**. If one route is busy or broken, packets simply take another. The internet you use today is still built on this idea, and it is why a cut cable in one place rarely takes the whole thing down.\n\n## What this means for you\n\nEvery time you load a web page, send an email or submit a repair report, your data is chopped into packets and sent on its way. You will see this in action in the module on how the internet works.\n\n::: try\nIn a few lessons you will trace a real packet route yourself. For now, just notice how the map in the image looks like a handful of hubs with many links, not one big central switch. That is the shape of resilience.\n:::\n\n## Further reading\n\n- [A Brief History of the Internet (Internet Society)](https://www.internetsociety.org/internet/history-internet/brief-history-internet/)', 3, '1969', 1969 FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'Why did the packet-switched design of ARPANET matter so much?', 0 FROM DUAL WHERE @lesson > 0;
SET @q := IF(@lesson > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'Messages can find another route if one path fails, so there is no single point of failure' AS t, 1 AS c, 'Resilience through many routes is still the internet\'s defining feature.' AS e, 0 AS s
  UNION ALL SELECT 'It made messages impossible to read' AS t, 0 AS c, 'Security and video came later. The key idea was resilience through packets and many routes.' AS e, 1 AS s
  UNION ALL SELECT 'It meant every computer needed a unique password' AS t, 0 AS c, 'Security and video came later. The key idea was resilience through packets and many routes.' AS e, 2 AS s
  UNION ALL SELECT 'It let people send video for the first time' AS t, 0 AS c, 'Security and video came later. The key idea was resilience through packets and many routes.' AS e, 3 AS s) o WHERE @q > 0;
