  UNION ALL SELECT 'A complete email' AS t, 0 AS c, 'It is a well-known story: the very first attempt only got two letters through.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Vint Cerf, Bob Kahn and TCP/IP: the network of networks', 'How separate networks were joined into one internet by a shared set of rules.', '![Vint Cerf in 2010](https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Vint_Cerf_-_2010.jpg/330px-Vint_Cerf_-_2010.jpg)\n\n## The problem: networks that could not talk\n\nBy the early 1970s there were several different computer networks, built by different groups, each using its own rules. A computer on one could not talk to a computer on another. It was like having several countries each with a different language and no translators.\n\nIn 1974 Vint Cerf and Bob Kahn published a design for a common set of rules that any network could adopt, so that data could cross from one network into another. The rules were split into two cooperating parts, which is why you will always see them together:\n\n- **IP (Internet Protocol)** handles addressing and routing: it gives every device an address and gets each packet one hop closer to its destination.\n- **TCP (Transmission Control Protocol)** handles reliability: it numbers the packets, checks that all have arrived, asks for re-sends of any missing ones, and puts them back in order.\n\n## The "flag day"\n\nOn 1 January 1983, ARPANET switched over to TCP/IP. Many people mark this as the real birth of **the internet**: not a single network, but a **network of networks** all speaking the same language. Anyone could join, as long as they followed the rules.\n\n## Why "protocol" is a word worth knowing\n\nA **protocol** is simply an agreed set of rules for how two parties communicate. You use protocols constantly without noticing: the order of a phone call (hello, who is speaking, purpose, goodbye) is a protocol. The internet is built on layers of protocols, each doing one job: TCP/IP carries packets, HTTP (coming soon) carries web requests, SMTP carries email.\n\nStandardising on open protocols is why a Samsung phone can open a page from a Linux server in a data centre in Ireland, with no prior arrangement. It is also a lesson for this project: **agreed standards are what let systems from different suppliers work together.**\n\n::: repairs\nWhen a supplier says their product "uses open standards" or "has a standard API", they are pointing at the same principle. It is the difference between a system that plugs into others and one that needs a costly custom link to each.\n:::\n\n::: try\nVisit `https://www.whatismyip.com` or search "what is my IP address". That number is the address that IP uses to find your connection. Notice that it is probably not unique to you: your home or office router shares it with every device behind it.\n:::\n\n## Further reading\n\n- [Vint Cerf (Computer History Museum)](https://computerhistory.org/profile/vint-cerf/)', 4, '1983', 1983 FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'What does IP (Internet Protocol) mainly do?', 0 FROM DUAL WHERE @lesson > 0;
SET @q := IF(@lesson > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'Checks all packets arrived and puts them in order' AS t, 0 AS c, 'That describes TCP, the reliability partner to IP.' AS e, 0 AS s
  UNION ALL SELECT 'Encrypts the data' AS t, 0 AS c, 'That describes TCP, the reliability partner to IP.' AS e, 1 AS s
  UNION ALL SELECT 'Addresses devices and routes each packet towards its destination' AS t, 1 AS c, 'IP is about addressing and routing. TCP handles reliability.' AS e, 2 AS s
  UNION ALL SELECT 'Stores web pages' AS t, 0 AS c, 'That describes TCP, the reliability partner to IP.' AS e, 3 AS s) o WHERE @q > 0;
