INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'It guarantees every website is safe' AS t, 0 AS c, 'Open standards help interoperability, but not safety, price or ownership.' AS e, 0 AS s
  UNION ALL SELECT 'It makes all internet access free' AS t, 0 AS c, 'Open standards help interoperability, but not safety, price or ownership.' AS e, 1 AS s
  UNION ALL SELECT 'It means only one company controls the internet' AS t, 0 AS c, 'Open standards help interoperability, but not safety, price or ownership.' AS e, 2 AS s
  UNION ALL SELECT 'Any device or network can join and talk to any other without special arrangements' AS t, 1 AS c, 'Agreed standards are what let different suppliers\' systems work together.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Tim Berners-Lee and the World Wide Web', 'A physicist at CERN invented a way to link documents across the internet, giving us URLs, HTTP and HTML.', '![Tim Berners-Lee](https://upload.wikimedia.org/wikipedia/commons/thumb/7/7e/Tim_Berners-Lee_CP_2.jpg/330px-Tim_Berners-Lee_CP_2.jpg)\n\n## The internet had existed for years, but it was hard to use\n\nBy the late 1980s the internet connected universities and research labs, but you needed to know exactly where information was held and how to retrieve it from each different system. At CERN, the European particle physics laboratory near Geneva, a British software engineer called Tim Berners-Lee felt this pain daily: thousands of researchers, many different computers, documents scattered everywhere.\n\nIn March 1989 he proposed a system to fix it, memorably described by his boss as "vague but exciting". By 1990 he had built the key pieces on a NeXT computer, and the world\'s first web server ran on a similar machine.\n\n## Three simple inventions\n\nThe **World Wide Web** is not the internet. It is a service that runs on top of it, made of three ideas that are still in use today:\n\n- **URL** (Uniform Resource Locator): a unique address for any document, such as `https://www.gov.scot/news`.\n- **HTTP** (HyperText Transfer Protocol): the rules for asking a server for a document and getting an answer. You will meet HTTP again and again in this course. It is the foundation of APIs.\n- **HTML** (HyperText Markup Language): a simple way of writing a document with **links** that point to other documents anywhere in the world.\n\nTogether these let anyone publish a page and let anyone else read it just by clicking.\n\n## A gift to the world\n\nIn April 1993 CERN put the web\'s core technology into the public domain, with no fees and no licences. That decision is a big reason the web became universal instead of one of several competing commercial systems.\n\n::: try\nVisit the recreated first website at `http://info.cern.ch`. It is plain text with a few links, and it is built from the same three ideas as every page you use today. Then right-click anywhere on a page and choose "View page source" (or press Ctrl+U on Windows, Option+Cmd+U on Mac) to see the HTML behind it.\n:::\n\n::: remember\nThe internet = the network (the roads). The web = a service running on it (the shops and libraries). HTTP, HTML and URLs are the three inventions that made the web.\n:::\n\n## Further reading\n\n- [History of the World Wide Web (Wikipedia)](https://en.wikipedia.org/wiki/History_of_the_World_Wide_Web)', 5, '1989', 1989 FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'What is the difference between the internet and the World Wide Web?', 0 FROM DUAL WHERE @lesson > 0;
SET @q := IF(@lesson > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'The internet is the global network; the web is one service that runs on top of it' AS t, 1 AS c, 'Email, video calls and APIs also use the internet without being "the web".' AS e, 0 AS s
  UNION ALL SELECT 'They are exactly the same thing' AS t, 0 AS c, 'They are related but not identical: the web came later and sits on the internet.' AS e, 1 AS s
  UNION ALL SELECT 'The web is the older of the two' AS t, 0 AS c, 'They are related but not identical: the web came later and sits on the internet.' AS e, 2 AS s
  UNION ALL SELECT 'The internet only carries email' AS t, 0 AS c, 'They are related but not identical: the web came later and sits on the internet.' AS e, 3 AS s) o WHERE @q > 0;
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'Which of these was NOT one of Berners-Lee\'s three core inventions?', 1 FROM DUAL WHERE @lesson > 0;
