INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'URL' AS t, 0 AS c, 'That one was one of the three original ideas.' AS e, 0 AS s
  UNION ALL SELECT 'The encrypted padlock (HTTPS)' AS t, 1 AS c, 'Encryption was added later. The original three were URL, HTTP and HTML.' AS e, 1 AS s
  UNION ALL SELECT 'HTTP' AS t, 0 AS c, 'That one was one of the three original ideas.' AS e, 2 AS s
  UNION ALL SELECT 'HTML' AS t, 0 AS c, 'That one was one of the three original ideas.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Mosaic and the browser: the web goes mainstream', 'How the first easy-to-use graphical browser, and what followed, turned a research tool into everyday life.', '![wide: NCSA Mosaic, the first widely used graphical browser (1993). Click to open full size.](https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/NCSA_Mosaic_Browser_Screenshot.png/960px-NCSA_Mosaic_Browser_Screenshot.png)\n\n## Making the web look like a web\n\nThe early web was mostly text. In 1993 a team at the University of Illinois (the NCSA), including Marc Andreessen and Eric Bina, released **Mosaic**, a browser that could show images inline with text, had buttons you could click, and ran on ordinary desktop computers. It was easy to install and use, and it took off.\n\nAndreessen soon co-founded Netscape, whose Navigator browser launched in 1994. Microsoft\'s Internet Explorer followed in 1995, starting the "browser wars". Later browsers you may recognise: Firefox (2004), Safari (2003), Chrome (2008) and Microsoft Edge (rebuilt on Chrome\'s engine in 2020).\n\n## The decade that followed\n\nBetween 1995 and 2005, in a flurry:\n\n- **Online shops and search**: Amazon and eBay (both 1995), Google (1998).\n- **Dot-com boom and bust**: huge investment, then a crash around 2000, after which the survivors were the businesses with real value.\n- **Broadband** replaced dial-up, making rich pages and video practical.\n- **Social media and "Web 2.0"**: sites where users create content rather than just read it.\n- **APIs begin to appear**: around 2000, companies like Salesforce and eBay started offering ways for other software to talk to theirs. We will pick this thread up in the API module.\n\n## What changed for ordinary organisations\n\nIn the 1990s a council website was an online leaflet. Over time it became a place to do things: pay, report, apply. Citizens\' expectations were set by the best online experiences they had anywhere, not by what other councils did. That expectation gap is a big part of why this project exists.\n\nIn 2012 the UK Government launched the single GOV.UK website, built around user needs and designed to a common standard, which became an influential model for public services including in Scotland.\n\n::: try\nGo to `https://web.archive.org` (the Internet Archive\'s Wayback Machine) and type in a website you know, perhaps a local council\'s. Pick an early year and click through. You are looking at a snapshot of what that site looked like back then. How much has changed? How much has not?\n:::\n\n## Further reading\n\n- [Internet Archive Wayback Machine](https://web.archive.org/)', 6, '1993', 1993 FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
