  UNION ALL SELECT 'It was the first search engine' AS t, 0 AS c, 'The internet and the web existed before Mosaic. Its contribution was ease of use.' AS e, 1 AS s
  UNION ALL SELECT 'It was an easy-to-use graphical browser that made the web accessible to ordinary people' AS t, 1 AS c, 'Usability, not invention, was its contribution: images, clicking and easy installation.' AS e, 2 AS s
  UNION ALL SELECT 'It introduced HTTPS' AS t, 0 AS c, 'The internet and the web existed before Mosaic. Its contribution was ease of use.' AS e, 3 AS s) o WHERE @q > 0;
