  UNION ALL SELECT 'On-premises' AS t, 0 AS c, 'In that model you would manage much more yourself than in this scenario.' AS e, 1 AS s
  UNION ALL SELECT 'SaaS (Software as a Service)' AS t, 1 AS c, 'With SaaS, you use the finished software and the supplier runs everything underneath.' AS e, 2 AS s
