INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'Contractors report that the new repairs app "works fine in the office but constantly times out in tenants\' flats and stairwells". The supplier says "it works on our test connection". Using what you now know about bandwidth, latency, packets and HTTPS, what would you ask the supplier and the contractors to help find the cause?', 'Good questions would include: what connection type and signal strength are affected users on (mobile data indoors is very different from office Wi-Fi)? Is it slow everywhere, or only in particular buildings or areas? Is it latency (each action pauses) or bandwidth (large photo uploads fail)? Does the app need a live connection for every action, or can it work offline and sync later? What size are the photos being uploaded and are they compressed on the phone before sending? Are timeouts set too short for a slow network? Is the connection encrypted end to end without extra delay from proxies or VPNs? The supplier\'s "works on our test connection" is a hint that testing was done in ideal conditions: ask them to test on a throttled or real mobile connection, ideally with a contractor in a real stairwell. The underlying lesson is that internet quality is variable, and a service needs to be designed for the worst realistic conditions its users face.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Module 4: The Browser and the Web Page =====
INSERT INTO pm_learning_modules (course_id, title, description, sort_order)
SELECT @course, 'The Browser and the Web Page', 'What your browser actually does, what a web page is made of, and how to look under the bonnet using the tools already built into your browser. This is the first hands-on module.', 4 FROM DUAL WHERE @course > 0;
SET @mod := IF(@course > 0, LAST_INSERT_ID(), 0);

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'What a browser really does', 'The request-response conversation that sits behind every click.', '## The browser is a translator and a courier\n\nA **browser** (Edge, Chrome, Safari, Firefox) does two main jobs:\n\n1. **Fetch**: it asks servers for things (pages, images, data) on your behalf.\n2. **Display**: it takes the raw code that comes back and turns it into the page you see.\n\nThat is it. Everything else, such as tabs, bookmarks, passwords and extensions, is convenience.\n\n## The request-response conversation\n\nEvery interaction on the web is a conversation with the same shape: the browser sends a **request**, the server sends back a **response**. One click may trigger dozens of these.\n\n![A client sends a request to a server and gets a response](local:request-response.svg)\n\nThe browser is the **client** (the one asking). The server is... the server (the one answering). Remember these two words, because they are the vocabulary of the whole course, and of APIs especially.\n\nHere is what really happens when you type `https://www.gov.scot` and press Enter:\n\n1. The browser asks DNS for the IP address of `www.gov.scot`.\n2. It opens a secure connection to that address.\n3. It sends a request, saying in effect "GET me the home page".\n4. The server replies with a response containing **HTML** (the page\'s structure), and the browser reads that and realises it also needs **CSS** (style), **JavaScript** (behaviour) and many images.\n5. The browser sends more requests for each of those, often 50 to 200 for one page.\n6. It assembles everything into the page you see, usually in under a second or two.\n\n## Things that make it faster\n\n- **Caching**: the browser saves copies of things that rarely change (logos, style sheets) so next time it does not have to ask again. This is why a page loads faster the second time, and why you sometimes see old content until you "hard refresh" (Ctrl+Shift+R, or Cmd+Shift+R on a Mac).\n- **Compression** and **content delivery networks** (CDNs), which keep copies of popular files on servers near you.\n\n::: try\nOpen any website, then press `Ctrl+Shift+R` (Windows) or `Cmd+Shift+R` (Mac) to reload it ignoring the cache. Notice whether it loads more slowly. That slower load is what a **first visit** feels like. The difference is the cache at work.\n:::\n\n::: remember\nClient asks, server answers. Request, response. This pattern is the root of APIs too, so make sure it feels natural.\n:::', 1, NULL, NULL FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
