SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'The real website was changed for everyone' AS t, 0 AS c, 'Your browser only edited its own copy, not the server\'s.' AS e, 0 AS s
  UNION ALL SELECT 'Only the copy in your own browser changed; the real website was untouched' AS t, 1 AS c, 'The browser holds its own copy of the page. Changes there are local and temporary.' AS e, 1 AS s
  UNION ALL SELECT 'The supplier received a change request' AS t, 0 AS c, 'Your browser only edited its own copy, not the server\'s.' AS e, 2 AS s
  UNION ALL SELECT 'The page was permanently broken' AS t, 0 AS c, 'Your browser only edited its own copy, not the server\'s.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Developer tools: the browser\'s x-ray machine', 'A guided tour of the built-in tool that shows you exactly what every page, form and API call is doing.', '## A free tool you already have\n\nEvery modern browser has **developer tools** built in. They are the single best way for a non-technical person to see how a system really behaves, and to describe a problem precisely to a developer. "The save button does nothing" is not much use. "I pressed save and the Network tab shows a request that came back with a 500 error" is gold.\n\nOpen them with `F12`, or `Ctrl+Shift+I` (Windows), or `Cmd+Option+I` (Mac), or right-click a page and choose **Inspect**.\n\n## The four tabs worth knowing\n\n- **Elements**: the page\'s HTML and CSS, live and editable (you used this in the last lesson).\n- **Console**: messages and errors from the page\'s JavaScript. It is also a place where you can type your own small commands, which we will use in the API module.\n- **Network**: a live list of every request your browser makes and every response it gets. **This is the important one for understanding APIs.**\n- **Application** (or **Storage**): cookies and data the site has saved in your browser. We cover that in the next lesson.\n\n## The Network tab, step by step\n\nWhen you open the Network tab and then load a page, a waterfall of rows appears. Each row is one request. Useful columns:\n\n- **Name**: what was requested.\n- **Status**: the response code (200 means fine, 404 means not found, 500 means the server failed).\n- **Type**: document (the HTML page), stylesheet, script, image, or **fetch/XHR**, which is where **API calls** appear.\n- **Size** and **Time**: how heavy and how slow.\n\nClick any row and you can see the **Headers** (the labels on the envelope), the **Payload** (what was sent) and the **Response** (what came back).\n\n::: try\n**Watch a page load, and spot an API call.**\n1. Open `https://www.gov.scot` in a new tab, then press `F12`.\n2. Click the **Network** tab, then reload the page (`Ctrl+R` or `Cmd+R`).\n3. Watch the rows fill up. Count them (the total is at the bottom). How many requests did one page take?\n4. Click the **Fetch/XHR** filter at the top. Any rows that remain are the page calling an API to fetch data in the background. If there are none on that page, try a site with search-as-you-type, such as `https://www.bbc.co.uk` or Google, and type in the search box with the Network tab open. Watch a new row appear as you type.\n5. Click one of those rows and choose the **Response** or **Preview** tab. You are reading the raw data that the page is about to turn into the results you see.\n\nThat, right there, is an API call, seen with your own eyes.\n:::\n\n::: repairs\nWhen something is wrong in a repairs portal, a screenshot of the **Network** tab with the failing red row is the most valuable thing you can send to a supplier. It shows exactly which request failed and what the system answered.\n:::', 3, NULL, NULL FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
