  UNION ALL SELECT 'Console' AS t, 0 AS c, 'That tab shows something else (page structure, messages or code). Requests are in the Network tab.' AS e, 1 AS s
  UNION ALL SELECT 'Network' AS t, 1 AS c, 'The Network tab lists every request and response, which is where API calls show up.' AS e, 2 AS s
  UNION ALL SELECT 'Sources' AS t, 0 AS c, 'That tab shows something else (page structure, messages or code). Requests are in the Network tab.' AS e, 3 AS s) o WHERE @q > 0;
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
