INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'A contractor says: "The repairs web app keeps logging me out in the middle of filling in a job report, and I lose everything." The supplier replies "that is a security feature". Using what you now know about sessions, cookies and the browser, what would you want to understand and what would you propose?', 'Security and usability are both legitimate, so the aim is a sensible balance. Questions: how long is the inactivity timeout, and does it count typing as activity (some do not)? Is the session ending because of a timeout, or because the cookie is being dropped by the phone\'s browser or an in-app browser? Does the app autosave a draft so a timeout does not lose work? Does it warn before logging out? Proposals: save a draft locally every few seconds, warn two minutes before expiry and offer to extend, extend the timeout for authenticated devices or on-site working while shortening it for shared PCs, and use "remember this device" with multi-factor authentication for contractors on their own phones. A Network tab check while reproducing the fault would show which request got the "401 not authorised" response, which tells the supplier exactly when the session died. The principle is that a security control that destroys people\'s work will be bypassed, which is worse for security.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Module 5: APIs: How Systems Talk to Each Other =====
