INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'The contractor\'s mobile app marks jobs as "complete" by sending the full job record back to the housing system using PUT. After a software update, completed jobs start losing their appointment times and the tenant\'s access notes. Using what you know about methods, status codes and data formats, what is likely to have happened, and what would you ask the supplier to do?', 'PUT replaces the whole record. If the updated app now sends only some of the fields (perhaps leaving out the appointment time and access notes because they are no longer on the screen), the system treats the missing fields as empty and wipes them. It is the classic PUT-versus-PATCH trap. Questions for the supplier: is the endpoint PUT or PATCH, and what does it do with fields it does not receive? Could the app switch to PATCH and send only the status and completion details? Could the API reject incomplete PUT bodies with a 400 or 422 error instead of silently accepting them? Do they keep an audit log of changes so lost data can be restored? Ask for a test case that proves the fix, and check that old records can be recovered from the history or backups. For the longer term, ask that the API contract (documentation) states clearly how omitted fields are treated.', 0 FROM DUAL WHERE @mod > 0;

