INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Websites, apps and everything in between', 'Responsive sites, native apps, progressive web apps, and how to choose for contractors and tenants.', '## Four ways to put a service on a phone\n\nMobile phones went from novelty to the main way most people use the internet. When someone says "we need an app" there are really several options.\n\n**1. A responsive website.** An ordinary website designed to rearrange itself to fit any screen size, from phone to desktop. No installation, works on everything, one thing to maintain. The default choice for public services, and the one the UK government recommends for most things.\n\n**2. A native app.** Built specifically for iPhone (in Apple\'s languages) or Android (Google\'s), distributed through the app stores. Best access to the phone\'s features (camera, GPS, push notifications, offline storage) and smoothest feel, but costs more, needs separate builds for each platform, and has to be installed and updated by every user.\n\n**3. A cross-platform app.** One codebase that produces both iPhone and Android apps (tools such as React Native or Flutter). A middle path on cost, with near-native feel.\n\n**4. A Progressive Web App (PWA).** A website that can be "installed" on the home screen, work offline, and send notifications. It gets many app benefits without an app store, though some phone features, especially on iPhone, remain limited.\n\n## Choosing: ask who is using it and where\n\n- **Tenants** reporting a repair once or twice a year will not install an app for it. A great mobile website wins.\n- **Contractors and operatives** using the system all day, often with no signal, taking photos and capturing signatures, may well justify a native or offline-capable app.\n- **Staff in an office** are best served by a web application on their desktop.\n\nMany councils end up with a portal for tenants, a mobile app for operatives, and a web back office for staff, all built on the **same back end and APIs**.\n\n## Things that matter on a phone\n\n- **Offline working**: can the app store work and sync later when signal returns?\n- **Camera, location and signatures**: are they supported and easy?\n- **Speed on poor connections**: heavy pages and large images are the enemy.\n- **Updates**: native apps need users to update them, so old versions linger. Servers need to cope with several versions in the wild.\n- **Device mix**: contractors use old, cracked, mid-range phones, not the latest model.\n- **App store rules**: you need accounts, compliance with Apple and Google policies, and review times.\n\n## The public sector view\n\nThe Scottish and UK public sector guidance strongly favours services that work in a browser on any device, and that are accessible to everyone. An app should usually be an addition for particular needs, not a replacement for a good web service.\n\n::: try\n**Test whether a site is responsive.** Open a council website on a computer. Drag the edge of the browser window narrower and watch the layout rearrange itself into a phone layout. Now press `F12` and click the little **device toolbar** (phone and tablet icon) to simulate specific phones. Does the service still work? Can you tap every button easily with a thumb?\n:::\n\n::: repairs\nFor an operative app, write the five jobs it must do **with no signal** (view today\'s jobs, record work, take photos, capture a signature, submit when back in coverage). If a supplier cannot demonstrate each of those in airplane mode, ask why.\n:::', 5, NULL, NULL FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
