INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'A supplier proposes replacing the 15-year-old repairs system with a new SaaS product, and says "it has an API, so connecting it to finance, customer support and the contractors\' apps will be straightforward". Using what you have learned about legacy systems, architecture, data and testing, what would you want to find out before believing this, and what would you want to see during this project?', 'Questions before believing it: Is the API documented in a standard form (OpenAPI), and can we see it? Does it cover everything we need (create, read, update, status changes, attachments) or only some read operations? Which style (REST, SOAP) and which authentication? How are rate limits, versioning and breaking changes handled? What are the real integration costs for each connected system, and who does the work? What happens to the data in the old system: how is it migrated, cleaned and mapped (different names, codes and date formats)? Can the old and new run side by side during transition, or is it a risky big-bang switch? During this project: a map of every integration and its owner, early proof-of-concept calls, realistic UAT scenarios written by repairs experts, a test environment with realistic data, regression testing on every release, a rollback plan and clear criteria for go-live. The claim "it has an API" is the start of the conversation, not the end of it.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Module 7: Design: How Digital Services Are Shaped =====
INSERT INTO pm_learning_modules (course_id, title, description, sort_order)
