INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'The Repairs project team is under pressure to "just build the new repairs portal" and skip user research because "we already know what tenants want". You have been asked to make the case for spending four weeks on discovery first. What would you say, and what would you propose doing in those four weeks?', 'The case: building the wrong thing is by far the most expensive mistake, and assumptions about users are often wrong, especially across diverse tenants with different needs, abilities and levels of digital confidence. Discovery is cheap by comparison and de-risks the big spend. It also produces evidence to support the business case and meets the expectations of the Digital Scotland Service Standard. In four weeks: interview and observe tenants, contractors\' operatives, customer support staff and planners; analyse existing contact data to find the top reasons for failure demand; map the current repair journey and systems landscape end to end, with handovers; identify the accessibility and inclusion needs of the tenant group; review what other councils and housing providers have done; sketch and test a few low-fidelity prototypes of the key moments; define success measures; and finish with a clear recommendation, including the option not to build something new if the evidence points elsewhere. Frame it as buying certainty rather than delay.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Module 8: Data, Security and Trust =====
INSERT INTO pm_learning_modules (course_id, title, description, sort_order)
SELECT @course, 'Data, Security and Trust', 'Why data quality decides everything, what the law says about personal data, how cyber attacks actually happen, and where AI and automation fit and do not fit.', 8 FROM DUAL WHERE @course > 0;
SET @mod := IF(@course > 0, LAST_INSERT_ID(), 0);

INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Data: quality, ownership and reporting', 'Why messy data quietly breaks everything, and the ideas of master data, standards and open data.', '## Software is only as good as its data\n\nIt is tempting to see digital transformation as buying clever systems. In practice the biggest problems are nearly always about **data**. A beautifully designed system that is fed incorrect, duplicated or inconsistent records produces wrong reports, mis-sent appointments and angry tenants.\n\n**Data quality** has several dimensions:\n\n- **Accuracy**: is it correct? (Is the phone number right?)\n- **Completeness**: is anything missing? (A third of repairs have no access notes.)\n- **Consistency**: do systems agree? (The tenant\'s name is spelled three ways.)\n- **Timeliness**: is it up to date? (A tenant moved out last month.)\n- **Uniqueness**: is each thing recorded once? (No duplicate properties.)\n- **Validity**: does it follow the expected format and rules? (A postcode that is actually a postcode.)\n\n## "Rubbish in, rubbish out"\n\nIf a repair is logged with a free-text description such as "kitchen leak??", you cannot count how many leaks happened last year or spot a pattern in a particular block. Structured data (a selected problem category, a location in the property, a photo) can be analysed and automated. The more structure at the point of entry, the more useful everything downstream becomes. The price is slightly more effort at the front, so good design makes structured entry quick and easy.\n\n## Master data and "one version of the truth"\n\n**Master data** is the core shared information about the things the organisation cares about: properties, tenants, suppliers, contractors, rate codes (such as the Schedule of Rates). Ideally each is held in **one trusted place** and other systems refer to it rather than keeping their own copies. When every system keeps its own copy of the property list, they drift apart, and every integration becomes a mapping exercise.\n\nA common thread in failed integration projects is that nobody was clearly **responsible** for the data. **Data ownership** (a named person accountable for a dataset\'s quality and use) is a governance matter, not an IT matter.\n\n## Standards\n\nUsing agreed identifiers and codes makes data joinable: for example the **UPRN** (Unique Property Reference Number) that identifies every addressable property in Great Britain. If every system keys property data on the UPRN, they can talk about the same property without guesswork.\n\n## Reporting and dashboards\n\nMost reporting is **business intelligence (BI)**: collecting data from several systems into a **data warehouse** or similar, and showing it in dashboards (tools such as Power BI are common in councils). A dashboard is only as trustworthy as the data and definitions underneath it. Agree definitions first: what counts as "completed on time"? From when does the clock start? Two teams using the same words differently will produce numbers that disagree.\n\n## Open data\n\nThe public sector publishes datasets openly, often through APIs, for anyone to use. This supports transparency and lets others build useful things. Scotland has a national open data portal and a national policy on open data.\n\n::: try\n**Explore real open data about places and housing in Scotland.** Visit `https://statistics.gov.scot` and browse the datasets (search for "housing" or a council area). Notice how the data is described: who published it, when it was updated, what each column means, and what licence applies. That description is called **metadata**, and good metadata is what makes data usable.\n\nThen call a real open API: open `https://api.postcodes.io/postcodes/EH99%201SP` again and look at the codes returned, such as council area and ward codes. Those standard codes are what allow different datasets to be joined together.\n:::\n\n::: repairs\nList five fields in the repairs data that you suspect are unreliable (for example "date completed", "trade type", "priority"). For each, who enters it, how, and what checks happen? That list is the beginning of a data quality plan, and a good guide to what a new system must validate.\n:::', 1, NULL, NULL FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
