INSERT INTO pm_learning_lessons (module_id, title, summary, content, sort_order, year_label, year_sort)
SELECT @mod, 'Cyber security for everyone', 'How attacks really happen, which habits stop most of them, and the Scottish public sector context.', '## Most attacks start with a person\n\nThe movies show hackers cracking code. In reality most breaches begin when someone is **tricked**. That includes the most careful people on a busy Friday afternoon.\n\n**Phishing** is a fraudulent message (email, text, phone call, even a Teams message) designed to make you reveal a password, open a malicious attachment, click a fake login page or approve a payment. Typical signs: urgency ("act now or lose access"), unexpected requests, slightly wrong sender addresses, links that do not go where they say, requests to bypass the normal process.\n\nOther common attacks:\n\n- **Ransomware**: malicious software that locks an organisation\'s files and demands payment. Several UK councils and the Scottish Environment Protection Agency have been hit by serious ransomware attacks, with services disrupted for weeks or months.\n- **Credential stuffing**: attackers try passwords leaked from one site on many others, because people reuse them.\n- **Supply chain attacks**: attackers compromise a *supplier* to get at its customers. For a council with many suppliers, this matters a lot.\n- **Insider mistakes**: sending data to the wrong person, losing a device, leaving a screen unlocked.\n\n## Habits that stop most attacks\n\n- **Multi-factor authentication (MFA)**: a password plus a second proof such as a code on your phone. This single measure blocks the large majority of account takeovers.\n- **Strong, unique passwords**, ideally with a **password manager**. A long passphrase of three random words is stronger than a short complicated one.\n- **Keep software updated.** Most attacks exploit weaknesses for which a fix already exists.\n- **Be suspicious of urgency.** Verify unexpected requests using a different channel.\n- **Report quickly.** Reporting a mistake straight away often prevents a disaster. A culture where people feel safe to say "I think I clicked something" is a security asset.\n- **Least privilege**: people and systems get only the access they need.\n- **Backups**, tested, and kept offline or immutable so ransomware cannot touch them.\n\n## Security by design in digital projects\n\nFor a system you are introducing, security means asking early: who can see what? How do people log in? Is every integration authenticated and logged? Is data encrypted in transit and at rest? How are updates applied? What happens if the supplier is compromised? Is there an independent **penetration test** (an ethical hacker attempting to break in) before go-live? Is there an **incident response plan**?\n\n## Standards and frameworks\n\n- **Cyber Essentials** and **Cyber Essentials Plus**: UK government-backed certification of basic security controls. Many public sector contracts require it.\n- The **Scottish Public Sector Action Plan on Cyber Resilience** sets expectations for public bodies in Scotland, and the **National Cyber Security Centre (NCSC)** publishes practical guidance for everyone.\n- **ISO 27001** is an international standard for information security management that some suppliers hold.\n\n::: try\n**Check whether your passwords have been leaked.** Visit `https://haveibeenpwned.com` and enter your email address (this well-known service is run by a security researcher and does not store your searches). If it shows breaches, that does not mean you were personally hacked, but it means a password you used there may be circulating, and you should change it everywhere you reused it.\n\n**Then test your phishing instincts.** Search for "Google phishing quiz" and take it. Most people miss at least one.\n:::\n\n::: repairs\nContractors, sub-contractors and their staff will all access the systems. Who is responsible for removing access when a contractor employee leaves? How quickly can a stolen phone\'s access be cut off? These are practical, process-based security questions colleagues can help answer.\n:::', 3, NULL, NULL FROM DUAL WHERE @mod > 0;
SET @lesson := IF(@mod > 0, LAST_INSERT_ID(), 0);
