INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'A supplier pitches an AI tool that reads tenants\' messages and photos and automatically sets the repair priority, promising "30% faster triage". Using what you know about data quality, GDPR, accessibility and AI risks, what would you ask before agreeing to a pilot, and how would you design the pilot safely?', 'Questions: What data was it trained on, and how was it tested on social housing repairs like ours? What is its measured accuracy, especially for urgent and safety-critical cases, and for different groups of tenants (different languages, writing styles, photos in poor light)? What happens when it is wrong, or uncertain? Where is personal data processed and stored, is it used to train the supplier\'s models, and what is the retention? Can we explain a priority decision to a tenant or the regulator? Safe pilot: run it in "shadow mode" at first, with its suggestions compared against human decisions and no effect on real priorities; always keep a human to confirm anything the tool rates as lower than a person would; carry out a DPIA and equality impact assessment before starting; set clear success and stop criteria (such as zero missed emergencies); monitor for bias; give tenants a clear route to a human; and have repairs staff review a sample of decisions each week. The 30% speed claim matters far less than whether any emergency is ever missed.', 0 FROM DUAL WHERE @mod > 0;

