SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'About 3.7 days' AS t, 0 AS c, 'Work it out: 0.1% of 8,760 hours in a year is about 8.8 hours.' AS e, 0 AS s
  UNION ALL SELECT 'About 53 minutes' AS t, 0 AS c, 'Work it out: 0.1% of 8,760 hours in a year is about 8.8 hours.' AS e, 1 AS s
  UNION ALL SELECT 'About 8.8 hours' AS t, 1 AS c, '0.1% of a year is about 8.8 hours.' AS e, 2 AS s
  UNION ALL SELECT 'None at all' AS t, 0 AS c, 'Work it out: 0.1% of 8,760 hours in a year is about 8.8 hours.' AS e, 3 AS s) o WHERE @q > 0;
