SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'The product becomes cheaper' AS t, 0 AS c, 'Customisation typically increases cost and complexity, not security or savings.' AS e, 0 AS s
  UNION ALL SELECT 'The product becomes more secure automatically' AS t, 0 AS c, 'Customisation typically increases cost and complexity, not security or savings.' AS e, 1 AS s
  UNION ALL SELECT 'You no longer need an SLA' AS t, 0 AS c, 'Customisation typically increases cost and complexity, not security or savings.' AS e, 2 AS s
