SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'The tenant\'s phone screen' AS t, 0 AS c, 'If the record was saved, those are unlikely culprits. Look at the hand-off between systems.' AS e, 0 AS s
  UNION ALL SELECT 'The integration, such as a failed webhook or API call to the contractor\'s system' AS t, 1 AS c, 'The data exists, so the break is probably in the connection between systems.' AS e, 1 AS s
  UNION ALL SELECT 'The colours on the form' AS t, 0 AS c, 'If the record was saved, those are unlikely culprits. Look at the hand-off between systems.' AS e, 2 AS s
  UNION ALL SELECT 'The domain name registration' AS t, 0 AS c, 'If the record was saved, those are unlikely culprits. Look at the hand-off between systems.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'At the next project board, a senior manager asks you in plain terms: "In one minute: what is an API, why are we paying so much for them, and what should we be worried about?" Write the answer you would give.', 'An API is a controlled doorway that lets one system ask another for information or to do something, using agreed rules, like a waiter between the dining room and the kitchen. We pay for them because our repairs service depends on many systems (housing, contractors, planners, finance, customer support, tenant portal) exchanging information accurately and automatically; without good APIs people re-key data, which is slow, error-prone and costs more in the long run. What to worry about: first, whether each system we buy has a well-documented, complete and secure API at all, because without it we pay for custom links or rely on fragile workarounds; second, data quality and clear ownership, since an integration just moves bad data faster; third, how the updates are done (partial or whole-record) and whether changes by one supplier can break another\'s link; fourth, security and data protection on every connection; and fifth, lock-in: we should be able to get our data out and swap a supplier without rebuilding everything. Good questions to ask the suppliers are: show us the API documentation, show us a working sandbox, and tell us what happens when it fails.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Glossary (existing terms are left untouched) =====
INSERT IGNORE INTO pm_learning_glossary (term, definition) VALUES
  ('API', 'Application Programming Interface: an agreed way for one piece of software to ask another to do something or share data, without needing to know how the other works inside.'),
  ('endpoint', 'A specific web address on an API that does one job, such as /repairs/4821 to fetch one repair. Think of it as one item on the API\'s menu.'),
  ('HTTP', 'HyperText Transfer Protocol: the set of rules browsers and apps use to ask servers for things and receive answers. HTTPS is the secure version.'),
  ('HTTPS', 'The secure version of HTTP. Traffic is encrypted so others on the network cannot read or tamper with it. Shown as a padlock in the browser.'),
  ('status code', 'A three-digit number a server sends back to say how a request went: 200 means fine, 404 not found, 500 server error.'),
  ('JSON', 'JavaScript Object Notation: a simple, readable text format for structured data, used by most modern APIs. Looks like {"priority": "urgent"}.'),
  ('payload', 'The actual data carried in a request or response, as opposed to the addressing and labelling around it.'),
  ('idempotent', 'A long word for "safe to repeat": doing it ten times gives the same result as doing it once. Marking a repair "Complete" twice is the same as once; creating a repair twice is not.'),
  ('REST', 'A popular style for designing APIs where each thing (a repair, a tenant) has its own address and you use standard HTTP methods like GET and POST to work with it.'),
  ('webhook', 'A reverse API call: instead of you repeatedly asking "has anything changed?", the other system calls a web address of yours the moment something happens.'),
  ('OAuth', 'A standard way of letting one app act on your behalf in another system without giving it your password. The "Sign in with Microsoft" pattern.'),
  ('API key', 'A long secret code that identifies which app is calling an API, a bit like a membership number. It must be kept private.'),
  ('token', 'A temporary digital pass issued after you log in, which your browser or app shows with each request to prove who you are.'),
  ('rate limit', 'A cap on how many requests an API will accept in a given time, to protect it from overload or misuse.'),
  ('integration', 'A connection between two systems so that data or actions flow between them without people re-keying anything.'),
  ('middleware', 'Software that sits between systems and passes, translates and routes data between them, so each does not need a custom link to every other.'),
  ('IP address', 'The numeric address of a device on a network, like 203.0.113.7. Every device that is online has one.'),
  ('DNS', 'Domain Name System: the internet\'s phone book, translating human-friendly names such as gov.scot into the numeric IP addresses computers use.'),
  ('domain name', 'The human-friendly name of a website or service, like gov.scot or example.org.uk.'),
  ('packet', 'A small chunk of data. Everything sent over the internet is broken into packets, sent separately and reassembled at the other end.'),
  ('router', 'A device that receives packets and forwards them towards their destination. The internet is millions of routers handing data along.'),
  ('server', 'A computer whose job is to answer requests from other computers, usually running all the time in a data centre.'),
  ('data centre', 'A secure building full of servers with power, cooling and network connections, run by a hosting or cloud company or by an organisation itself.'),
  ('cloud', 'Using computers owned and run by someone else (such as Microsoft, Amazon or Google) over the internet, instead of running your own servers.'),
  ('SaaS', 'Software as a Service: you use a finished application over the internet and the supplier looks after everything underneath, such as Microsoft 365 or most housing systems today.'),
  ('PaaS', 'Platform as a Service: a supplier provides the servers and runtime so developers only manage their own application and data.'),
  ('IaaS', 'Infrastructure as a Service: you rent raw servers, storage and networking and manage everything above that yourself.'),
  ('encryption', 'Scrambling data using a key so that only someone with the right key can read it.'),
  ('certificate', 'A digital document that proves a website really is who it claims to be, which is what makes HTTPS and the padlock possible.'),
  ('browser', 'The program, such as Edge, Chrome, Safari or Firefox, that requests web pages from servers and turns the answer into what you see.'),
  ('HTML', 'HyperText Markup Language: the code that defines the structure and content of a web page: headings, paragraphs, links, forms.'),
  ('CSS', 'Cascading Style Sheets: the code that controls how a web page looks: colours, fonts, spacing and layout.'),
  ('JavaScript', 'The programming language that runs inside your browser and makes pages interactive. Unrelated to Java despite the name.'),
  ('cookie', 'A small piece of data a website asks your browser to store, used to remember you between page loads, such as keeping you logged in.'),
  ('session', 'The period during which a system recognises you as the same logged-in person across many requests.'),
  ('cache', 'A saved copy of something so it can be served faster next time instead of being fetched again from the original source.'),
  ('latency', 'The delay between asking for something and starting to get it back. High latency feels laggy.'),
  ('front end', 'The part of a digital service people see and interact with: screens, buttons, forms. It runs in the browser or on the phone.'),
  ('back end', 'The part of a digital service people do not see: the servers, business rules and databases that do the real work.'),
  ('database', 'An organised store of data, usually arranged in tables of rows and columns, that software can search and update quickly and reliably.'),
  ('schema', 'The blueprint of a database: which tables exist, what columns each has, what type of value each holds and how the tables link together.'),
  ('primary key', 'The column (or columns) that uniquely identifies each row in a table, such as a repair reference number. No two rows share one.'),
  ('foreign key', 'A column that holds the primary key of a row in another table, creating a link between the two tables.'),
  ('DBMS', 'Database Management System: the software that runs a database, stores the data safely and carries out requests to read or change it. MySQL, PostgreSQL and SQL Server are examples.'),
  ('SQL', 'Structured Query Language: the standard language for asking a database questions or changing its data.'),
  ('monolith', 'An application built as one large, tightly connected unit, as opposed to many small separate services.'),
  ('microservices', 'An approach where an application is split into many small independent services, each doing one job and talking to the others through APIs.'),
  ('legacy system', 'An older system still in use that is hard to change or connect to, often because of its age, technology or lack of documentation.'),
  ('technical debt', 'The accumulated cost of shortcuts and ageing technology: things that work today but will be slower and riskier to change tomorrow.'),
  ('environment', 'A separate copy of a system used for a particular purpose, such as development, test or live, so that changes can be tried safely.'),
  ('UAT', 'User Acceptance Testing: the stage where the people who will actually use a system check that it does what the job really needs.'),
  ('version control', 'A system, most commonly Git, that records every change to code or documents, who made it and why, so that work can be compared and undone.'),
  ('CI/CD', 'Continuous Integration and Continuous Delivery: automated steps that test and release software changes quickly and safely.'),
  ('wireframe', 'A simple black-and-white sketch of a screen showing layout and content, used to agree what goes where before any design or build.'),
  ('prototype', 'A cheap, early version of a service, ranging from paper to a clickable mock-up, used to test ideas with real users before building properly.'),
  ('UX', 'User Experience: how easy, clear and pleasant it is to get something done with a service from start to finish.'),
  ('design system', 'A shared library of tested components, patterns and rules so that every service looks and behaves consistently, such as the GOV.UK Design System.'),
  ('accessibility', 'Designing so that everyone can use a service, including people with disabilities or using assistive technology such as screen readers.'),
  ('WCAG', 'Web Content Accessibility Guidelines: the international standard for accessible web content. UK public bodies must meet level AA (currently assessed against version 2.2).'),
  ('service design', 'Designing the whole end-to-end experience of a service, including the people, processes and systems behind the screen.'),
  ('user journey', 'The steps a person goes through to get something done, mapped out including their thoughts, feelings and pain points.'),
  ('discovery', 'The first phase of building a service, spent learning about the problem and the users before deciding what to build.'),
  ('data quality', 'How accurate, complete, consistent and up to date data is. Poor data quality quietly undermines every report and automated process built on it.'),
  ('master data', 'The core shared records an organisation relies on everywhere, such as properties, tenants and suppliers, ideally held once and trusted by every system.'),
  ('open data', 'Data published openly, under a licence that lets anyone use and reuse it, often via an API.'),
  ('UK GDPR', 'The UK General Data Protection Regulation: law governing how personal data may be collected, used, stored and shared. Works alongside the Data Protection Act 2018.'),
  ('personal data', 'Any information that identifies, or could identify, a living person: a name, an address, a repair record linked to a tenant.'),
  ('DPIA', 'Data Protection Impact Assessment: a structured check, required for higher-risk uses of personal data, that finds and reduces privacy risks before a system goes live.'),
  ('phishing', 'A fraudulent message designed to trick you into revealing a password, clicking a malicious link or taking a harmful action.'),
  ('MFA', 'Multi-factor authentication: proving who you are with two or more things, such as a password plus a code on your phone.'),
  ('SLA', 'Service Level Agreement: a contract term setting what a supplier promises, such as 99.9% uptime or a four-hour response to serious faults, and what happens if they miss it.'),
  ('uptime', 'The percentage of time a service is working and available. 99.9% allows about 8.8 hours of downtime a year.'),
  ('vendor lock-in', 'Being so dependent on one supplier\'s product or format that switching away becomes prohibitively costly or difficult.'),
  ('roadmap', 'A supplier\'s or team\'s plan of what they intend to build and in roughly what order. Intentions, not promises.'),
  ('generative AI', 'AI that produces new content such as text or images in response to a prompt, built on large models trained on vast amounts of data.'),
  ('RPA', 'Robotic Process Automation: software "robots" that copy what a person does on screen, such as copying data between systems, to automate repetitive tasks.');
